    Bug 2018063 - Make programmatic folder expansion synchronous and fix 0-height animation bugs. r=mkmelin


    Programmatic folder selection (`displayFolder`) was failing to scroll into view
    and causing race conditions with message selection because
    `folderTree.expandRow()` runs a 200ms asynchronous animation. Additionally,
    expanding or collapsing deeply nested hidden folders triggered overlapping
    0-height animations, which actively broke parent layout calculations.

    Differential Revision: https://phabricator.services.mozilla.com/D284400

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index bcb5777b698..30e4146c19c 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -6717,6 +6717,16 @@ function ensureFolderTreeRowIsVisible(row) {
       "#folderTree li.collapsed"
     );
   }
+
+  // Instantly fast-forward expansion animations to 100% completion.
+  for (const animation of folderTree.getAnimations({ subtree: true })) {
+    if (
+      !CSSAnimation.isInstance(animation) &&
+      !CSSTransition.isInstance(animation)
+    ) {
+      animation.finish();
+    }
+  }
 }

